    "memoryHowBody": "ONE Global nutzt diesen Verlauf, um sich an dein letztes Gespräch zu erinnern, während ihr weiter chattet (ungefähr die letzten 20 Hin-und-her-Nachrichten). Wenn du deine Geräte-/Browserdaten löschst oder auf „Verlauf löschen“ tippst, ist dieser Kontext komplett weg — es wird kein dauerhaftes Profil oder „erfundene Rückschlüsse“ über dich erstellt, es speichert einfach nur das Gespräch selbst.",
