    "devicesSoonTitle": "Demnächst",
    "devicesSoonBody1": "Funktionen wie Fernsteuerung von Geräten, Bildschirmfreigabe oder das Verwalten von Dateien/E-Mails in deinem Namen gibt es in ONE Global im Moment noch nicht — wir haben einen alten Demo-Bildschirm, der das versprach, durch diesen ehrlichen Hinweis ersetzt. Diese Art von Gerätesteuerung braucht eine echte Sicherheits-/Berechtigungsinfrastruktur und ist ein großes Vorhaben, das wir uns später separat ansehen.",
    "devicesSoonBody2": "Was ONE Global gerade wirklich kann: ein echtes KI-Gespräch, deine tägliche Benachrichtigungsroutine und das Merken deines Chatverlaufs — alles auf diesem Gerät. Da es noch kein Kontosystem gibt, sind deine Einstellungen und dein Chat an dieses Gerät/diesen Browser gebunden — auf deinem nächsten Gerät musst du sie erneut einrichten.",
