    "devicesSoonBody1": "Такие функции, как удалённое управление устройством, демонстрация экрана или работа с файлами/почтой от твоего имени, пока не существуют в ONE Global — вместо старого демо-экрана, который это обещал, мы поставили эту честную заметку. Такое управление устройствами требует настоящей инфраструктуры безопасности и разрешений — это большая задача, которую мы рассмотрим отдельно в будущем.",
