    "devicesSoonBody1": "रिमोट डिवाइस कंट्रोल, स्क्रीन शेयरिंग, या आपकी ओर से फ़ाइल/ईमेल संभालने जैसी सुविधाएँ अभी ONE Global में मौजूद नहीं हैं — हमने इनका वादा करने वाली एक पुरानी डेमो स्क्रीन की जगह यह ईमानदार नोट लगाया है। इस तरह के डिवाइस कंट्रोल के लिए एक असली सुरक्षा/परमिशन ढांचा चाहिए, और यह एक बड़ा काम है जिस पर हम आगे अलग से विचार करेंगे।",
    "devicesSoonBody2": "अभी ONE Global असल में जो करता है: इस डिवाइस पर एक असली AI बातचीत, आपकी रोज़ की नोटिफ़िकेशन रूटीन, और आपके चैट इतिहास को याद रखना। अभी कोई अकाउंट सिस्टम न होने की वजह से आपकी सेटिंग्स और चैट सिर्फ़ इसी डिवाइस/ब्राउज़र तक सीमित हैं — अगले डिवाइस पर आपको इन्हें फिर से सेट करना होगा।",
