    "memorySubtitle": "ONE Global-এর সাথে তোমার কথোপকথনের আসল চ্যাট ইতিহাস",
    "memoryWhatBody": "এই স্ক্রিনটা অ্যাসিস্ট্যান্ট ট্যাবে হওয়া তোমার আসল কথোপকথনের ইতিহাস — কোনো বানানো \"শেখা তথ্য\"-র লিস্ট নয়। এটা শুধু এই ডিভাইসের পরিচয়ের সাথে যুক্ত; তুমি চাইলে যেকোনো সময় নিচে থেকে এটা পুরোপুরি মুছে দিতে পারো।",
    "memoryHistoryTitle": "তোমার চ্যাট ইতিহাস",
    "memoryClearBtn": "ইতিহাস মুছুন",
    "memoryEmptyBody": "তোমার এখনো কোনো কথোপকথন নেই। অ্যাসিস্ট্যান্ট ট্যাব থেকে ONE Global-কে কিছু জিজ্ঞেস করো, তোমার ইতিহাস এখানে দেখা যাবে।",
    "memoryHowTitle": "ONE Global এটা কীভাবে ব্যবহার করে?",
    "memoryHowBody": "কথোপকথন চালিয়ে যাওয়ার সময় তোমার সাম্প্রতিক আলাপ মনে রাখতে ONE Global এই ইতিহাস ব্যবহার করে (মোটামুটি শেষ ২০টা আদান-প্রদান করা মেসেজ)। তুমি যদি ডিভাইস/ব্রাউজারের ডেটা মুছে ফেলো বা \"ইতিহাস মুছুন\"-এ ট্যাপ করো, তাহলে এই প্রসঙ্গ পুরোপুরি হারিয়ে যায় — এটা তোমার সম্পর্কে কোনো স্থায়ী প্রোফাইল বা \"বানানো অনুমান\" তৈরি করে না, শুধু কথোপকথনটাই সংরক্ষণ করে।",
    "memoryCountLabel": "{n}টি মেসেজ",
    "memoryLoadFailed": "ইতিহাস লোড করা গেল না।",
