    "devicesKicker": "কমান্ড সেন্টার",
    "devicesTitle": "ডিভাইস",
    "devicesSubtitle": "একাধিক ডিভাইসের মধ্যে আসল সিঙ্ক আর নিয়ন্ত্রণ এখনো ONE Global-এর অংশ নয়।",
    "devicesSoonTitle": "শীঘ্রই আসছে",
    "devicesSoonBody1": "রিমোট ডিভাইস কন্ট্রোল, স্ক্রিন শেয়ারিং, বা তোমার হয়ে ফাইল/ইমেইল সামলানোর মতো ফিচার এখন ONE Global-এ নেই — এসবের প্রতিশ্রুতি দেওয়া পুরোনো একটা ডেমো স্ক্রিনের বদলে আমরা এই সৎ নোটটা রেখেছি। এই ধরনের ডিভাইস কন্ট্রোলের জন্য দরকার একটা আসল নিরাপত্তা/পারমিশন কাঠামো, যা একটা বড় কাজ এবং ভবিষ্যতে আলাদাভাবে বিবেচনা করা হবে।",
    "devicesSoonBody2": "ONE Global এখন সত্যিই যা করে: এই ডিভাইসে একটা আসল AI কথোপকথন, তোমার প্রতিদিনের নোটিফিকেশন রুটিন, আর তোমার চ্যাট ইতিহাস মনে রাখা। এখনো কোনো অ্যাকাউন্ট সিস্টেম না থাকায় তোমার সেটিংস আর চ্যাট শুধু এই ডিভাইস/ব্রাউজারেই সীমাবদ্ধ — পরের ডিভাইসে তোমাকে আবার সেট করতে হবে।",
